def seed_initial_data(apps, schema_editor):
    database = schema_editor.connection.alias
    LinkType = apps.get_model("tasks", "LinkType")
    for name, outward, inward in (
        ("Relates", "relates to", "relates to"),
        ("Duplicate", "duplicates", "is duplicated by"),
        ("Blocks", "blocks", "is blocked by"),
        ("Cloners", "clones", "is cloned by"),
    ):
        LinkType.objects.using(database).create(
            name=name, outward_description=outward, inward_description=inward,
        )

    WorkType = apps.get_model("tasks", "WorkType")
    defaults = (
        ("Bug", "bug", "A defect or unexpected behavior that needs fixing."),
        ("Enabler", "enabler", "Technical work that supports future delivery."),
        ("Story", "story", "User-focused functionality or a requirement."),
        ("Improvement", "improvement", "An enhancement to existing functionality."),
        ("Task", "task", "A general piece of work."),
        ("Sub-task", "sub_task", "A smaller piece of work within a larger task."),
        ("Test", "test", "A test case or verification activity."),
        ("Test Plan", "test_plan", "A plan describing test scope and approach."),
        ("Test Execution", "test_execution", "A run of tests and their results."),
        ("Event", "event", "An event to plan, track, or record."),
    )
    WorkType.objects.using(database).bulk_create([
        WorkType(title=title, icon=icon, description=description, is_default=title == "Task")
        for title, icon, description in defaults
    ])
    apps.get_model("tasks", "RepositorySettings").objects.using(database).create(pk=1)

    try:
        port = int(getattr(settings, "ACP_PORT", ""))
    except (TypeError, ValueError):
        return
    if 1 <= port <= 65535:
        apps.get_model("tasks", "AcpEndpoint").objects.using(database).create(
            name="Default ACP", host="127.0.0.1", port=port, priority=1, enabled=True,
        )


